#include <iostream>
#include <string>
using namespace std;

class DongVat {
public:
    string ten;
    DongVat(string t) : ten(t) {}
    string keu() { return ten + " keu"; }
};

class Cho : public DongVat {
public:
    Cho(string t) : DongVat(t) {}
};

int main() {
    Cho c("Mun");
    cout << c.keu() << endl;
    return 0;
}
